import { loadStripe } from "@stripe/stripe-js";
import { PUBLIC_STRIPE_KEY } from "$app/env/public";
import type { EmbeddedCheckoutFactory } from "#lib/stripe/embedded-checkout-widget.js";

/**
 * Public regular-Workshop registration's Stripe. Stripe redirects to the
 * session's return URL on completion, so no completion callback is passed.
 */
export const createWorkshopRegistrationCheckout: EmbeddedCheckoutFactory =
	async ({ clientSecret }) => {
		const stripe = await loadStripe(PUBLIC_STRIPE_KEY);
		if (!stripe) {
			throw new Error(
				"Failed to initialize secure payment. Please refresh and try again.",
			);
		}
		return stripe.initEmbeddedCheckout({ clientSecret });
	};
