	if (snapshot.matches("initFailed")) return "initFailed";
	if (snapshot.matches("confirming")) return "confirming";
	if (snapshot.matches("confirmFailed")) return "confirmFailed";
	if (snapshot.matches("confirmed")) return "confirmed";
