import { assign, setup, type SnapshotFrom } from "xstate";
import {
	embeddedCheckoutWidget,
	type EmbeddedCheckoutWidgetEvent,
	type EmbeddedCheckoutWidgetInput,
} from "#lib/stripe/embedded-checkout-widget.js";

/**
 * Public regular-Workshop registration's embedded Checkout (ALE-447), one
 * actor per registration page (`useMachine`; never a module-scope actor).
 *
 * The page's load has already created the Checkout Session; this machine
 * owns only the widget's lifecycle. The widget is created after the host
 * sends `MOUNTED` from the mounted browser, exists only while `collecting`,
 * and is destroyed by leaving it or by stopping the actor. Stripe redirects
 * to the confirmation page itself on completion, so there is no confirmation
 * phase here. An initialization failure retries the same session; a missing
 * Stripe key or session is `unavailable`, which no retry can fix.
 *
 * This is deliberately not the Beginners' Workshop Intake machine: the two
 * share only the widget adapter.
 */

export type WorkshopRegistrationCheckoutInput = {
	clientSecret: string | null | undefined;
	stripeConfigured: boolean;
};

export type WorkshopRegistrationCheckoutContext = {
	clientSecret: string;
	/** The registration error shown to the member, if any. */
	error: string | null;
};

export type WorkshopRegistrationCheckoutEvent =
	| EmbeddedCheckoutWidgetEvent
	| { type: "MOUNTED" }
	| { type: "RETRY" };

export const PAYMENT_UNAVAILABLE =
	"Payment is currently unavailable. Please try again later.";
export const CHECKOUT_MISSING =
	"Failed to initialize checkout. Please refresh and try again.";
export const CHECKOUT_FAILED =
	"Failed to initialize checkout. Please try again.";

function failureMessage(cause: unknown): string {
	return cause instanceof Error && cause.message
		? cause.message
		: CHECKOUT_FAILED;
}

export const workshopRegistrationCheckoutMachine = setup({
	// SAFETY: `setup({ types })` reads only the types of these placeholders.
	types: {
		context: {} as WorkshopRegistrationCheckoutContext,
		events: {} as WorkshopRegistrationCheckoutEvent,
		input: {} as WorkshopRegistrationCheckoutInput,
	},
	actors: {
		// The host provides it through `embeddedCheckoutWidget` with its own
		// factory and container.
		widget: embeddedCheckoutWidget(
			async () => {
				throw new Error("widget must be provided by the host");
			},
			() => undefined,
		),
	},
}).createMachine({
	id: "workshopRegistrationCheckout",
	context: ({ input }) => ({
		clientSecret: input.clientSecret ?? "",
		error: !input.stripeConfigured
			? PAYMENT_UNAVAILABLE
			: input.clientSecret
				? null
				: CHECKOUT_MISSING,
	}),
	initial: "mounting",
	states: {
		mounting: {
			always: {
				guard: ({ context }) => !!context.error,
				target: "unavailable",
			},
			on: { MOUNTED: { target: "collecting" } },
		},
		collecting: {
			invoke: {
				src: "widget",
				input: ({ context }): EmbeddedCheckoutWidgetInput => ({
					clientSecret: context.clientSecret,
				}),
			},
			on: {
				"WIDGET.FAILED": {
					target: "initFailed",
					actions: assign({
						error: ({ event }) => failureMessage(event.error),
					}),
				},
			},
			initial: "loading",
			states: {
				loading: { on: { "WIDGET.MOUNTED": { target: "active" } } },
				active: {},
			},
		},
		initFailed: {
			on: {
				RETRY: { target: "collecting", actions: assign({ error: null }) },
			},
		},
		unavailable: {},
	},
});

export type WorkshopRegistrationCheckoutPhase =
	| "loading"
	| "active"
	| "initFailed"
	| "unavailable";

/** The leaf phase of a snapshot of `workshopRegistrationCheckoutMachine`. */
export function workshopRegistrationCheckoutPhase(
	snapshot: SnapshotFrom<typeof workshopRegistrationCheckoutMachine>,
): WorkshopRegistrationCheckoutPhase {
	if (snapshot.matches({ collecting: "active" })) return "active";
	if (snapshot.matches("initFailed")) return "initFailed";
	if (snapshot.matches("unavailable")) return "unavailable";
	return "loading";
}
