import type { StripeEmbeddedCheckoutOptions } from "@stripe/stripe-js";
import { describe, expect, it, vi } from "vitest";
import { createActor, waitFor } from "xstate";
import {
	embeddedCheckoutWidget,
	type EmbeddedCheckoutFactory,
	type EmbeddedCheckoutWidget,
} from "#lib/stripe/embedded-checkout-widget.js";
import {
	CHECKOUT_FAILED,
	CHECKOUT_MISSING,
	PAYMENT_UNAVAILABLE,
	workshopRegistrationCheckoutMachine,
	workshopRegistrationCheckoutPhase,
	type WorkshopRegistrationCheckoutInput,
} from "./workshop-registration-checkout-machine";

// SAFETY: only the fake widget's `mount` receives the container.
const container = {} as HTMLElement;

function harness(
	input: Partial<WorkshopRegistrationCheckoutInput> = {},
	create?: (
		options: StripeEmbeddedCheckoutOptions,
	) => Promise<EmbeddedCheckoutWidget>,
) {
	const widget = { mount: vi.fn(), destroy: vi.fn() };
	const factory = vi.fn<EmbeddedCheckoutFactory>(
		create ?? (async () => widget),
	);
	const actor = createActor(
		workshopRegistrationCheckoutMachine.provide({
			actors: { widget: embeddedCheckoutWidget(factory, () => container) },
		}),
		{
			input: {
				clientSecret: "cs_test_secret",
				stripeConfigured: true,
				...input,
			},
		},
	);
	const phase = () => workshopRegistrationCheckoutPhase(actor.getSnapshot());
	const error = () => actor.getSnapshot().context.error;
	return { actor, widget, factory, phase, error };
}

describe("workshopRegistrationCheckoutMachine", () => {
	it("mounts the session's widget after the browser mounts, and only then", async () => {
		const { actor, widget, factory, phase } = harness();
		actor.start();
		expect(phase()).toBe("loading");
		expect(factory).not.toHaveBeenCalled();

		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		expect(factory.mock.calls[0][0].clientSecret).toBe("cs_test_secret");
		expect(widget.mount).toHaveBeenCalledWith(container);
	});

	it.each([
		[{ stripeConfigured: false }, PAYMENT_UNAVAILABLE],
		[{ clientSecret: null }, CHECKOUT_MISSING],
	])("%o is unavailable without loading Stripe", (input, message) => {
		const { actor, factory, phase, error } = harness(input);
		actor.start();
		actor.send({ type: "MOUNTED" });
		expect(phase()).toBe("unavailable");
		expect(error()).toBe(message);
		expect(actor.getSnapshot().can({ type: "RETRY" })).toBe(false);
		expect(factory).not.toHaveBeenCalled();
	});

	it("an initialization failure shows its message and retries the same session", async () => {
		const widget = { mount: vi.fn(), destroy: vi.fn() };
		const create = vi
			.fn<(o: StripeEmbeddedCheckoutOptions) => Promise<typeof widget>>()
			.mockRejectedValueOnce(
				new Error(
					"Failed to initialize secure payment. Please refresh and try again.",
				),
			)
			.mockResolvedValue(widget);
		const { actor, phase, error } = harness({}, create);
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches("initFailed"));
		expect(error()).toBe(
			"Failed to initialize secure payment. Please refresh and try again.",
		);

		actor.send({ type: "RETRY" });
		expect(phase()).toBe("loading");
		expect(error()).toBeNull();
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		expect(create).toHaveBeenCalledTimes(2);
		expect(create.mock.calls[1][0].clientSecret).toBe("cs_test_secret");
	});

	it("a failure without a message gets the fallback copy", async () => {
		const { actor, error } = harness({}, () => Promise.reject("boom"));
		actor.start();
		actor.send({ type: "MOUNTED" });
		await waitFor(actor, (s) => s.matches("initFailed"));
		expect(error()).toBe(CHECKOUT_FAILED);
	});

	it("repeated retries and mounts start one widget at a time", async () => {
		const { actor, factory } = harness();
		actor.start();
		actor.send({ type: "MOUNTED" });
		actor.send({ type: "MOUNTED" });
		actor.send({ type: "RETRY" });
		await waitFor(actor, (s) => s.matches({ collecting: "active" }));
		expect(factory).toHaveBeenCalledOnce();
	});

	it("stopping destroys the mounted widget, and a late one is never mounted", async () => {
		const mounted = harness();
		mounted.actor.start();
		mounted.actor.send({ type: "MOUNTED" });
		await waitFor(mounted.actor, (s) => s.matches({ collecting: "active" }));
		mounted.actor.stop();
		expect(mounted.widget.destroy).toHaveBeenCalledOnce();

		const widget = { mount: vi.fn(), destroy: vi.fn() };
		let resolve!: (value: EmbeddedCheckoutWidget) => void;
		const late = harness({}, () => new Promise((done) => (resolve = done)));
		late.actor.start();
		late.actor.send({ type: "MOUNTED" });
		late.actor.stop();
		resolve(widget);
		await vi.waitFor(() => expect(widget.destroy).toHaveBeenCalledOnce());
		expect(widget.mount).not.toHaveBeenCalled();
	});
