			(container as HTMLElement).appendChild(rendered);
		}),
		destroy: vi.fn(() => rendered?.remove()),
	};
	const init = vi.fn(
		async (
			_options: StripeEmbeddedCheckoutOptions,
		): Promise<EmbeddedCheckoutWidget> => embedded,
	);
	return { embedded, init };
}

test("loads, then mounts the session's widget in place", async () => {
