			},
			() => undefined,
		),
	},
	guards: {
		stripeMissing: ({ context }) => !context.stripeConfigured,
		sessionMissing: ({ context }) => !context.clientSecret,
	},
}).createMachine({
	id: "workshopRegistrationCheckout",
