export function workshopRegistrationCheckoutView(
	snapshot: WorkshopRegistrationCheckoutSnapshot,
): WorkshopRegistrationCheckoutView {
	const phase = phaseOf(snapshot);
	return { phase, ...PRESENTATION[phase] };
}

