import { loadStripe, type Stripe } from "@stripe/stripe-js";
import { PUBLIC_STRIPE_KEY } from "$app/env/public";
import type { EmbeddedCheckoutFactory } from "#lib/stripe/embedded-checkout-widget.js";

type StripeLoader = () => Promise<Pick<Stripe, "initEmbeddedCheckout"> | null>;

/**
 * A factory for Checkout Sessions that redirect to their return URL on
 * completion. The widget actor's completion callback is deliberately not
 * passed on: Stripe refuses `onComplete` for sessions that always redirect.
 */
export function redirectingEmbeddedCheckout(
	load: StripeLoader,
): EmbeddedCheckoutFactory {
	return async ({ clientSecret }) => {
		const stripe = await load();
		if (!stripe) throw new Error("Stripe unavailable");
		return stripe.initEmbeddedCheckout({ clientSecret });
	};
}

/** Public regular-Workshop registration's Stripe. */
export const createWorkshopRegistrationCheckout = redirectingEmbeddedCheckout(
	() => loadStripe(PUBLIC_STRIPE_KEY),
);

import { describe, expect, it, vi } from "vitest";
import { redirectingEmbeddedCheckout } from "./workshop-registration-checkout-sdk";

describe("redirectingEmbeddedCheckout (ALE-447)", () => {
	it("passes only the session: the session redirects, so no completion callback", async () => {
		const widget = { mount: vi.fn(), destroy: vi.fn() };
		const initEmbeddedCheckout = vi.fn(async () => widget);
		const load = vi.fn(async () => ({ initEmbeddedCheckout }));

		await expect(
			redirectingEmbeddedCheckout(load)({
				clientSecret: "cs_test_secret",
				onComplete: () => {},
			}),
		).resolves.toBe(widget);
		expect(initEmbeddedCheckout).toHaveBeenCalledWith({
			clientSecret: "cs_test_secret",
		});
	});

	it("fails when Stripe cannot load", async () => {
		await expect(
			redirectingEmbeddedCheckout(async () => null)({
				clientSecret: "cs_test_secret",
			}),
		).rejects.toThrow();
	});
});

